Dataspatium.assets.register("presets/api/lantmateriet-ngp-detaljplan.api.json","text","{\n  \"format\": \"dataspatium-api/1\",\n  \"id\": \"lantmateriet-ngp-detaljplan\",\n  \"name\": \"Lantmäteriet geodataplattformen: detaljplaner (OGC API Features)\",\n  \"publisher\": \"Lantmäteriet\",\n  \"description\": \"Digitala detaljplaner från den nationella geodataplattformen (NGP): planområden och planbestämmelser enligt den nationella specifikationen. Kräver API-nyckel från en organisation som är ansluten till plattformen; nyckeln sparas aldrig i klartext.\",\n  \"docs\": \"https://www.lantmateriet.se/sv/nationella-geodataplattformen/\",\n  \"level\": 2,\n  \"country\": \"SE\",\n  \"baseUrl\": \"https://api.lantmateriet.se/distribution/geodatakatalog/sokning/v1/detaljplan/v2\",\n  \"auth\": {\n    \"type\": \"bearer\",\n    \"help\": \"API-nyckeln från anslutningen till Nationella geodataplattformen skickas som Bearer-token.\"\n  },\n  \"family\": {\n    \"type\": \"geodata\",\n    \"kind\": \"ogcapi\"\n  },\n  \"endpoints\": [],\n  \"notes\": \"Samlingarna hämtas från tjänsten när källan öppnas. CORS tillåter anrop från file://; utan nyckel svarar tjänsten 401.\",\n  \"i18n\": {\n    \"en\": {\n      \"name\": \"Lantmäteriet national geodata platform: detailed plans (OGC API Features)\",\n      \"description\": \"Digital detailed development plans from the national geodata platform (NGP): plan areas and provisions according to the national specification. Requires an API key from an organisation connected to the platform; the key is never stored in clear text.\",\n      \"notes\": \"The collections are read from the service when the source is opened. CORS allows file://; without a key the service answers 401.\"\n    },\n    \"da\": {\n      \"name\": \"Lantmäteriet geodataplatformen: lokalplaner (OGC API Features)\",\n      \"description\": \"Digitale lokalplaner fra den nationale geodataplatform (NGP): planområder og planbestemmelser efter den nationale specifikation. Kræver API-nøgle fra en organisation, der er tilsluttet platformen; nøglen gemmes aldrig i klartekst.\",\n      \"notes\": \"Samlingerne hentes fra tjenesten, når kilden åbnes. CORS tillader kald fra file://; uden nøgle svarer tjenesten 401.\"\n    },\n    \"nb\": {\n      \"name\": \"Lantmäteriet geodataplattformen: reguleringsplaner (OGC API Features)\",\n      \"description\": \"Digitale reguleringsplaner fra den nasjonale geodataplattformen (NGP): planområder og planbestemmelser etter den nasjonale spesifikasjonen. Krever API-nøkkel fra en organisasjon som er tilknyttet plattformen; nøkkelen lagres aldri i klartekst.\",\n      \"notes\": \"Samlingene hentes fra tjenesten når kilden åpnes. CORS tillater kall fra file://; uten nøkkel svarer tjenesten 401.\"\n    },\n    \"fi\": {\n      \"name\": \"Lantmäteriet paikkatietoalusta: asemakaavat (OGC API Features)\",\n      \"description\": \"Digitaaliset asemakaavat kansallisesta paikkatietoalustasta (NGP): kaava-alueet ja kaavamääräykset kansallisen määrittelyn mukaan. Vaatii API-avaimen alustaan liittyneeltä organisaatiolta; avainta ei koskaan tallenneta selväkielisenä.\",\n      \"notes\": \"Kokoelmat noudetaan palvelusta, kun lähde avataan. CORS sallii kutsut file://-sivuilta; ilman avainta palvelu vastaa 401.\"\n    },\n    \"is\": {\n      \"name\": \"Landupplýsingavettvangur Lantmäteriet: deiliskipulag (OGC API Features)\",\n      \"description\": \"Stafrænt deiliskipulag af landsvettvangi landupplýsinga (NGP): skipulagssvæði og skipulagsákvæði samkvæmt landsforskriftinni. Krefst API-lykils frá stofnun sem er tengd vettvanginum; lykillinn er aldrei vistaður í hreinum texta.\",\n      \"notes\": \"Söfnin eru sótt úr þjónustunni þegar uppsprettan er opnuð. CORS leyfir köll frá file://; án lykils svarar þjónustan 401.\"\n    }\n  }\n}\n");
